-- ---------------------------------------------------------------------
-- Encounter portraits
--
-- Painted by tools/paint_portraits.py and baked into PORTRAIT_DATA (the
-- part before this one) as 1-bit 32x32 sprite tiles, base64 text. Only the
-- creature on screen is decoded, and only once: PORTRAIT_CACHE holds one
-- subject, so memory stays at a few KB whatever the roster grows to.
--
-- The picture reacts to the fight: far away it is small, near it fills the
-- frame, close up you see its face; wounds show as it gets hurt; dead or
-- fled changes it again.
-- ---------------------------------------------------------------------

local PORTRAIT_SIZE = 96

local B64_VAL = {}   -- base64 digit -> value
do
    local digits = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    for i = 1, #digits do B64_VAL[digits:byte(i)] = i - 1 end
end

local function b64_decode(text)
    local out, n = {}, 0
    for i = 1, #text, 4 do
        local a, b = B64_VAL[text:byte(i)], B64_VAL[text:byte(i + 1)]
        local c3, d4 = text:byte(i + 2), text:byte(i + 3)
        local c, d = B64_VAL[c3], B64_VAL[d4]
        local v = (a << 18) | (b << 12) | ((c or 0) << 6) | (d or 0)
        n = n + 1; out[n] = string.char((v >> 16) & 0xff)
        if c then n = n + 1; out[n] = string.char((v >> 8) & 0xff) end
        if d then n = n + 1; out[n] = string.char(v & 0xff) end
    end
    return table.concat(out)
end

local PORTRAIT_CACHE = {who = nil, views = {}, empty = string.rep("\0", 128)}

-- The tiles of one view ({x, y, data} per non-empty 32x32 tile), decoded on
-- first use. Returns nil for a subject with no art.
local function portrait_view(who, view)
    local entry = PORTRAIT_DATA[who]
    if not entry or not entry[view] then return nil end
    if PORTRAIT_CACHE.who ~= who then
        PORTRAIT_CACHE.who, PORTRAIT_CACHE.views = who, {}
    end
    local cached = PORTRAIT_CACHE.views[view]
    if cached then return cached end
    local v = entry[view]
    local bytes = b64_decode(v.data)
    local tiles = {}
    for ty = 0, v.th - 1 do
        for tx = 0, v.tw - 1 do
            local k = (ty * v.tw + tx) * 128
            local tile = bytes:sub(k + 1, k + 128)
            if tile ~= PORTRAIT_CACHE.empty then
                tiles[#tiles + 1] = {x = tx * 32, y = ty * 32, data = tile}
            end
        end
    end
    cached = {w = v.w, h = v.h, th = v.th, tiles = tiles, marks = v.marks}
    PORTRAIT_CACHE.views[view] = cached
    return cached
end

-- How many wound marks to show for a fraction of health left (the same
-- bands as Game:enemy_condition: unhurt > 0.75, hurt > 0.4, else badly).
function Game.wound_count(frac)
    if frac > 0.75 then return 0 elseif frac > 0.4 then return 5 end
    return 11
end

-- Draw the portrait for encounter e in a 96x96 frame at (x, y).
function Game:draw_portrait(e, x, y)
    local size = PORTRAIT_SIZE
    gfx.color(gfx.WHITE)
    gfx.fill_rect(x, y, size, size)
    gfx.color(gfx.BLACK)
    local who = e.def.art
    local fights = e.def.hp ~= nil
    if e.outcome == "fled" then
        gfx.rect(x, y, size, size)
        gfx.font(gfx.FONT_MONO_12)
        gfx.text(x + size // 2 - 14, y + size // 2 + 4, "gone")
        return
    end
    -- far: the small view low in the frame, as if across the field;
    -- close: the face fills it; near (and everything that doesn't fight): all of it
    local view = "near"
    if fights and e.outcome ~= "dead" then
        if e.range == "far" then view = "far" elseif e.range == "close" then view = "close" end
    end
    local v = who and portrait_view(who, view)
    if v then
        -- tiles are 32x32, so a 48 px view is padded to 64: place by the
        -- padded size so no tile hangs outside the frame (far sits low-ish)
        local ox = x + (size - v.w) // 2
        local oy = y + size - v.th * 32
        for _, t in ipairs(v.tiles) do
            draw_sprite(ox + t.x, oy + t.y, 32, 32, t.data)
        end
        -- wounds: small dark blots on the creature, more as it weakens
        local frac = fights and math.max(0, e.hp / e.def.hp) or 1
        local n = e.outcome == "dead" and #v.marks // 2 or Game.wound_count(frac)
        local r = view == "far" and 1 or 2
        for i = 1, math.min(n, #v.marks // 2) do
            local mx, my = v.marks[2 * i - 1], v.marks[2 * i]
            gfx.fill_rect(ox + mx - r, oy + my - r, 2 * r + 1, 2 * r)
            gfx.fill_rect(ox + mx - r + 1, oy + my + r, 2 * r - 1, r + 1)   -- a drip
        end
    end
    if e.outcome == "dead" then
        -- dead: a dark hatch across the picture
        gfx.color(gfx.DARK)
        for k = -size, size, 6 do
            local x0, x1 = math.max(0, k), math.min(size - 1, k + size - 1)
            if x1 > x0 then gfx.line(x + x0, y + x0 - k, x + x1, y + x1 - k) end
        end
        gfx.color(gfx.BLACK)
    end
    gfx.rect(x, y, size, size)
end
-- ---------------------------------------------------------------------
-- Story moments (texts in QUESTS.scenes): a short full-screen scene, once a
-- run, at a few turning points. Game:queue_scene(id) from the moment's own
-- code; the main loop shows queued scenes only from the map screen (so the
-- tests and the balance sim, which call methods directly, never see one).
-- self.scenes_seen = {id = true} (saved; an old save counts all as seen).
-- ---------------------------------------------------------------------

function Game:queue_scene(id)
    self.scenes_seen = self.scenes_seen or {}
    if self.scenes_seen[id] or not QUESTS.scenes[id] then return false end
    self.scenes_seen[id] = true
    self.scene_queue = self.scene_queue or {}
    table.insert(self.scene_queue, id)
    return true
end

-- From the main loop: true if a scene is now on screen.
function Game:show_queued_scene()
    local q = self.scene_queue
    if self.screen ~= "map" or not q or #q == 0 then return false end
    self.scene = table.remove(q, 1)
    self.screen = "scene"
    return true
end

function Game:scene_key()
    self.scene = nil
    self.screen = "map"
end

-- Every scene counted as seen (old saves: nothing replays).
function Game.all_scenes_seen()
    local seen = {}
    for _, id in ipairs(QUESTS.scenes.order) do seen[id] = true end
    return seen
end

function Game:draw_scene(w, h)
    local sc = QUESTS.scenes[self.scene] or QUESTS.scenes.wake
    gfx.clear(gfx.WHITE)
    gfx.color(gfx.BLACK)
    gfx.font(gfx.FONT_BOLD_14)
    gfx.text(10, 24, sc.title)
    gfx.font(gfx.FONT_MONO_12)
    local cols = 54
    if sc.art and draw_sprite then
        self:draw_portrait({def = {art = sc.art}}, w - PORTRAIT_SIZE - 10, 34)
        gfx.color(gfx.BLACK)
        gfx.rect(w - PORTRAIT_SIZE - 11, 33, PORTRAIT_SIZE + 2, PORTRAIT_SIZE + 2)
        cols = (w - PORTRAIT_SIZE - 30) // 7
    end
    local y = 50
    for _, line in ipairs(wrap(sc.text, cols)) do
        gfx.text(10, y, line)
        y = y + 16
    end
    gfx.text(10, h - 8, "Any key to go on")
end
-- ---------------------------------------------------------------------
-- The intro: a splash on every launch ("THE CHURN" in big block letters,
-- a slowly turning eye, an epigraph), then the title menu, then - for a
-- new survivor - a short story crawl before the creator.
--   screen "intro" -> "title" -> "crawl" -> "creator"
-- The tests and the balance sim build games with Game.new() and never
-- pass through here; only the main loop does (Game:begin_intro).
-- ---------------------------------------------------------------------

Game.INTRO = {
    -- 5x7 block letters, "#" = filled
    glyphs = {
        T = {"#####", "..#..", "..#..", "..#..", "..#..", "..#..", "..#.."},
        H = {"#...#", "#...#", "#...#", "#####", "#...#", "#...#", "#...#"},
        E = {"#####", "#....", "#....", "####.", "#....", "#....", "#####"},
        C = {".####", "#....", "#....", "#....", "#....", "#....", ".####"},
        U = {"#...#", "#...#", "#...#", "#...#", "#...#", "#...#", ".###."},
        R = {"####.", "#...#", "#...#", "####.", "#.#..", "#..#.", "#...#"},
        N = {"#...#", "##..#", "#.#.#", "#.#.#", "#..##", "#...#", "#...#"},
    },
    title = "THE CHURN", cell = 5, eye_r = 44,
    epigraph = {"The land does not lie still. It turns over in its",
                "sleep, and what it turns up, it remembers."},
    -- New survivor: the story so far, a page at a time
    crawl = {
        {"THE INSTITUTE",
         "There was an Institute out by the old quarry. The town was told the hum "
         .. "was a transformer fault, and not to talk about the birds. Lorries came "
         .. "at night with crates that were warm to the touch. One of them, a "
         .. "driver swore, was singing."},
        {"THE FIRST EMISSION",
         "Then the sky over the quarry turned purple and breathed. Nobody outside "
         .. "lived. Those in the cellars came up two days later into fields that "
         .. "had changed: grass in spirals, dogs that came back wrong, roads that "
         .. "no longer went where they had gone."},
        {"THE CHURN",
         "The land began to turn. Not fast; the way a sleeper turns. Hills fold, "
         .. "rivers drift a field to the left, and what was buried comes up again: "
         .. "tins, tapes, guns, bones. The soldiers fenced it off and called it "
         .. "the Churn. They let no one out without paper."},
        {"YOU",
         "You wake in the grass with nothing. Not even shoes. Somewhere there is "
         .. "a Trader, and past him a Checkpoint. Learn what the dead knew - their "
         .. "books, their tapes, their drives - and walk out. Or stay, and be "
         .. "turned over with the rest."},
    },
}

-- Start-up from the main loop: the splash first, then the title menu.
function Game:begin_intro(saved)
    self.title_save = saved
    self.title_cursor = 1
    self.intro_phase = 0
    self.screen = "intro"
end

-- Big letters from runs of filled cells (one fill_rect per run).
function Game.draw_big_text(text, x, y, cell)
    local G = Game.INTRO.glyphs
    for i = 1, #text do
        local rows = G[text:sub(i, i)]
        if rows then
            for ry, row in ipairs(rows) do
                local start
                for cx = 1, #row + 1 do
                    local on = row:sub(cx, cx) == "#"
                    if on and not start then start = cx end
                    if not on and start then
                        gfx.fill_rect(x + (start - 1) * cell, y + (ry - 1) * cell, (cx - start) * cell, cell)
                        start = nil
                    end
                end
            end
        end
        x = x + 6 * cell
    end
end

-- The turning eye: three spiral arms around a pupil, rotated by phase.
function Game:draw_intro_eye(cx, cy, phase)
    local R = Game.INTRO.eye_r
    gfx.color(gfx.WHITE)
    gfx.fill_rect(cx - R - 2, cy - R - 2, 2 * R + 5, 2 * R + 5)
    gfx.color(gfx.BLACK)
    gfx.circle(cx, cy, R)
    for arm = 0, 2 do
        local px, py
        for s = 0, 14 do
            local t = s / 14
            local a = phase * 0.35 + arm * 2.094 + t * 4.2
            local r = 8 + t * (R - 10)
            local x, y = cx + math.floor(r * math.cos(a)), cy + math.floor(r * math.sin(a) * 0.8)
            if px then gfx.line(px, py, x, y) end
            px, py = x, y
        end
    end
    gfx.fill_circle(cx, cy, 6)
    gfx.color(gfx.WHITE)
    gfx.pixel(cx - 2, cy - 2)
    gfx.color(gfx.BLACK)
end

function Game:draw_intro(w, h)
    local I = Game.INTRO
    gfx.clear(gfx.WHITE)
    gfx.color(gfx.BLACK)
    local tw = (#I.title * 6 - 1) * I.cell
    Game.draw_big_text(I.title, (w - tw) // 2, 18, I.cell)
    self:draw_intro_eye(w // 2, 120, self.intro_phase or 0)
    gfx.font(gfx.FONT_MONO_12)
    for i, line in ipairs(I.epigraph) do
        gfx.text((w - #line * 7) // 2, 196 + (i - 1) * 16, line)
    end
    self:draw_intro_prompt(w, h)
    gfx.refresh()
end

function Game:draw_intro_prompt(w, h)
    local text = "- press any key -"
    gfx.color(gfx.WHITE)
    gfx.fill_rect(0, h - 40, w, 20)
    gfx.color(gfx.BLACK)
    gfx.font(gfx.FONT_MONO_12)
    if (self.intro_phase or 0) % 4 ~= 3 then gfx.text((w - #text * 7) // 2, h - 26, text) end
end

-- An idle poll on the splash: turn the eye a little (only it is redrawn).
function Game:intro_tick(w, h)
    self.intro_phase = (self.intro_phase or 0) + 1
    self:draw_intro_eye(w // 2, 120, self.intro_phase)
    self:draw_intro_prompt(w, h)
    gfx.refresh()
end

function Game:intro_key(key)
    if key == KEY.Q then
        self.quit = true
    else
        self.screen = "title"
    end
end

-- The title menu: Continue (with a save), New survivor.
function Game:title_rows()
    local rows = {}
    local d = self.title_save
    if d then
        rows[#rows + 1] = {("Continue  (day %d, %d HP)"):format(
            (WORLD.start_hour + d.player.hours) // 24 + 1, math.floor(d.player.health or 0)), "continue"}
    end
    rows[#rows + 1] = {"New survivor", "new"}
    return rows
end

function Game:draw_title(w, h)
    gfx.clear(gfx.WHITE)
    gfx.color(gfx.BLACK)
    local I = Game.INTRO
    local tw = (#I.title * 6 - 1) * 3
    Game.draw_big_text(I.title, (w - tw) // 2, 40, 3)
    gfx.font(gfx.FONT_MONO_12)
    local sub = "a survival game"
    gfx.text((w - #sub * 7) // 2, 80, sub)
    for i, row in ipairs(self:title_rows()) do
        local y = 130 + (i - 1) * 24
        if i == self.title_cursor then
            gfx.fill_rect(w // 2 - 110, y - 13, 220, 18)
            gfx.color(gfx.WHITE)
        end
        gfx.text(w // 2 - 100, y, row[1])
        gfx.color(gfx.BLACK)
    end
    gfx.text(6, h - 8, "Up/Dn pick  Enter choose  R records  Q quit")
    gfx.refresh()
end

function Game:title_key(key)
    local rows = self:title_rows()
    if key == gfx.KEY_UP or key == KEY.W then
        self.title_cursor = math.max(1, self.title_cursor - 1)
    elseif key == gfx.KEY_DOWN or key == KEY.S then
        self.title_cursor = math.min(#rows, self.title_cursor + 1)
    elseif key == KEY.ENTER or key == KEY.LF or key == KEY.SPACE then
        local pick = rows[self.title_cursor] or rows[#rows]
        if pick[2] == "continue" then
            self:load_state(self.title_save)
        else
            self.crawl_page = 1
            self.screen = "crawl"
        end
        self.title_save = nil
    end
end

function Game:draw_crawl(w, h)
    local page = Game.INTRO.crawl[self.crawl_page or 1]
    gfx.clear(gfx.WHITE)
    gfx.color(gfx.BLACK)
    gfx.font(gfx.FONT_BOLD_14)
    gfx.text(14, 40, page[1])
    gfx.font(gfx.FONT_MONO_12)
    local y = 74
    for _, line in ipairs(wrap(page[2], 52)) do
        gfx.text(14, y, line)
        y = y + 18
    end
    gfx.text(w - 60, 22, ("%d/%d"):format(self.crawl_page or 1, #Game.INTRO.crawl))
    gfx.text(6, h - 8, "Enter: on   Esc: skip")
    gfx.refresh()
end

function Game:crawl_key(key)
    if key == gfx.KEY_ESCAPE or key == KEY.Q then
        self.screen = "creator"
    elseif key == KEY.ENTER or key == KEY.LF or key == KEY.SPACE or key == gfx.KEY_RIGHT or key == KEY.D then
        self.crawl_page = (self.crawl_page or 1) + 1
        if self.crawl_page > #Game.INTRO.crawl then self.screen = "creator" end
    end
end
-- ---------------------------------------------------------------------
-- Character creator screen
-- rows 1..#ATTRIBUTES are attributes, the rest are TRAITS in order
-- ---------------------------------------------------------------------

local CREATOR_ROWS = #ATTRIBUTES + #TRAITS
-- attributes in the left column, traits in the right (from CREATOR_TRAIT_X),
-- the highlighted row's description and the resulting build below both
local CREATOR_ATTR_Y, CREATOR_TRAIT_Y, CREATOR_ROW_H = 52, 52, 14
local CREATOR_TRAIT_X = 200

function Game:creator_key(key)
    local p = self.player
    local row = self.creator_cursor
    self.creator_msg = nil
    if key == gfx.KEY_UP or key == KEY.W then
        self.creator_cursor = math.max(1, row - 1)
    elseif key == gfx.KEY_DOWN or key == KEY.S then
        self.creator_cursor = math.min(CREATOR_ROWS, row + 1)
    elseif (key == gfx.KEY_LEFT or key == KEY.A or key == gfx.KEY_RIGHT or key == KEY.D)
        and row <= #ATTRIBUTES then
        local name = ATTRIBUTES[row]
        local up = key == gfx.KEY_RIGHT or key == KEY.D
        if up and p.attrs[name] < ATTR_MAX and attr_points_left(p.attrs) > 0 then
            p.attrs[name] = p.attrs[name] + 1
        elseif up and attr_points_left(p.attrs) <= 0 then
            self.creator_msg = "No points left: lower another first."
        elseif not up and p.attrs[name] > ATTR_MIN then
            p.attrs[name] = p.attrs[name] - 1
        end
        recompute_stats(p)
    elseif key == KEY.SPACE and row > #ATTRIBUTES then
        local t = TRAITS[row - #ATTRIBUTES]
        p.traits[t.name] = not p.traits[t.name] or nil
        recompute_stats(p)
    elseif key >= 49 and key <= 51 then   -- 1/2/3: difficulty
        self:set_difficulty(DIFFICULTY.order[key - 48])
    elseif key == KEY.ENTER or key == KEY.LF then
        self:start_game()
    end
end

function Game:draw_creator(w, h)
    local p = self.player
    gfx.clear(gfx.WHITE)
    gfx.color(gfx.BLACK)
    gfx.font(gfx.FONT_BOLD_14)
    gfx.text(6, 16, "Create your survivor")
    gfx.font(gfx.FONT_MONO_12)
    gfx.text(210, 16, "Difficulty 1-3: " .. DIFFICULTY[self.difficulty or "normal"].short)

    gfx.text(6, 36, "Attributes  left " .. attr_points_left(p.attrs))
    for i, name in ipairs(ATTRIBUTES) do
        local y = CREATOR_ATTR_Y + (i - 1) * CREATOR_ROW_H
        local v = p.attrs[name]
        gfx.text(6, y, (self.creator_cursor == i and ">" or " ") .. name)
        for c = 1, ATTR_MAX do
            local cx = 100 + (c - 1) * 12
            if c <= v then gfx.fill_rect(cx, y - 9, 10, 9) else gfx.rect(cx, y - 9, 10, 9) end
        end
        gfx.text(176, y, tostring(v))
    end

    local tleft = trait_points_left(p.traits)
    gfx.text(CREATOR_TRAIT_X, CREATOR_TRAIT_Y - 16, "Traits  left " .. tleft)
    for i, t in ipairs(TRAITS) do
        local row = #ATTRIBUTES + i
        local y = CREATOR_TRAIT_Y + (i - 1) * CREATOR_ROW_H
        local mark = p.traits[t.name] and "[x] " or "[ ] "
        gfx.text(CREATOR_TRAIT_X, y, (self.creator_cursor == row and ">" or " ") .. mark .. t.name)
        -- what it does to the budget: positives spend, negatives give
        local cost = (t.cost > 0 and "-" or "+") .. math.abs(t.cost)
        gfx.text(w - 6 - 7 * #cost, y, cost)
    end

    -- the highlighted row explained, then the build it gives
    local y = CREATOR_TRAIT_Y + #TRAITS * CREATOR_ROW_H + 6
    gfx.line(6, y - 10, w - 6, y - 10)
    local row = self.creator_cursor
    local desc = row <= #ATTRIBUTES and ATTR_DESC[ATTRIBUTES[row]]
        or TRAITS[row - #ATTRIBUTES].desc
    gfx.text(6, y + 4, desc)
    local bag = POCKET_CELLS + p.bag_bonus   -- (you start with nothing: no bag, no pockets)
    gfx.text(6, y + 20, "MP " .. p.max_mp .. " Sight " .. p.sight .. " Finds " .. p.scav_rolls
        .. " Duds " .. dud_percent(p.attrs.Perception) .. "%")
    gfx.text(6, y + 34, "Carry " .. math.max(2, math.min(BACKPACK_CAP, bag)) .. " (no bag, no clothes)")
    if self.creator_msg then
        gfx.text(6, y + 50, self.creator_msg)
    elseif tleft < 0 then
        gfx.text(6, y + 50, "Trait points below 0: can't start.")
    end

    gfx.text(6, h - 20, "Up/Dn row  L/R attribute")
    gfx.text(6, h - 8, "Spc trait  Enter start  R records  Q quit")
    gfx.refresh()
end

-- Encounter screen: name, description, what just happened, status, and the
-- numbered choices (at most 7 rows fit above the bottom edge).
function Game:draw_encounter(w, h)
    local e, p = self.enc, self.player
    gfx.clear(gfx.WHITE)
    gfx.color(gfx.BLACK)
    gfx.font(gfx.FONT_BOLD_14)
    gfx.text(6, 16, e.def.name)
    gfx.font(gfx.FONT_MONO_12)
    for i, line in ipairs(e.intro) do gfx.text(6, 22 + 13 * i, line) end
    self:draw_portrait(e, w - 102, 18)
    gfx.color(gfx.BLACK)
    gfx.font(gfx.FONT_MONO_12)
    gfx.line(6, 114, w - 108, 114)
    for i, line in ipairs(e.msg) do gfx.text(6, 116 + 13 * i, line) end
    local status = "You " .. math.floor(p.health) .. " HP"
    if p.injuries.bleeding then status = status .. " bleeding" end
    if e.def.hp then
        status = "Range " .. RANGE_NAME[e.range] .. "   " .. status
            .. "   It: " .. (e.seen and self:enemy_condition() or "?")
    end
    gfx.text(6, 186, status)
    gfx.line(6, 192, w - 6, 192)
    for i, o in ipairs(self:encounter_options()) do
        gfx.text(6, 194 + 13 * i, (i == e.cursor and ">" or " ") .. i .. " " .. o[1])
    end
    gfx.refresh()
end

-- A rune: a box with a needle pointing up/right/down/left (0-3).
local function draw_rune(x, y, size, dir)
    gfx.rect(x, y, size, size)
    local cx, cy, r = x + size // 2, y + size // 2, size // 2 - 4
    local dx, dy = ({0, 1, 0, -1})[dir + 1], ({-1, 0, 1, 0})[dir + 1]
    gfx.fill_rect(cx - 2, cy - 2, 5, 5)
    for t = -1, 1 do
        gfx.line(cx + t * dy, cy + t * dx, cx + dx * r + t * dy, cy + dy * r + t * dx)
    end
end

function Game:draw_puzzle(w, h)
    local z = self.puz
    gfx.clear(gfx.WHITE)
    gfx.color(gfx.BLACK)
    gfx.font(gfx.FONT_BOLD_14)
    gfx.text(6, 16, self.enc.def.name)
    gfx.font(gfx.FONT_MONO_12)
    if z.kind == "bolts" then
        gfx.text(6, 34, "Your detector clicks once for each deadly spot")
        gfx.text(6, 47, "next to you. Reach the glint at the top.")
        local cell = 32
        local x0, y0 = (w - cell * BOLT_N) // 2, 58
        for c = 1, BOLT_N * BOLT_N do
            local x = x0 + ((c - 1) % BOLT_N) * cell
            local y = y0 + ((c - 1) // BOLT_N) * cell
            gfx.color(gfx.BLACK)
            gfx.rect(x, y, cell + 1, cell + 1)
            if z.revealed[c] and z.haz[c] then
                gfx.color(gfx.DARK)
                gfx.fill_rect(x + 2, y + 2, cell - 3, cell - 3)
            elseif z.visited[c] and c ~= z.pos then
                gfx.text(x + 13, y + 21, tostring(bolt_count(z.haz, c)))
            elseif z.revealed[c] then
                gfx.fill_rect(x + 14, y + 14, 5, 5)
            end
            if c == BOLT_GOAL then
                gfx.color(gfx.BLACK)
                gfx.rect(x + 8, y + 8, 17, 17)
                gfx.rect(x + 12, y + 12, 9, 9)
            end
        end
        local px = x0 + ((z.pos - 1) % BOLT_N) * cell
        local py = y0 + ((z.pos - 1) // BOLT_N) * cell
        gfx.color(gfx.BLACK)
        gfx.fill_rect(px + 6, py + 6, cell - 11, cell - 11)
        gfx.color(gfx.WHITE)
        gfx.text(px + 13, py + 21, tostring(bolt_count(z.haz, z.pos)))
        gfx.color(gfx.BLACK)
        gfx.text(6, 238, "Bolts: " .. z.bolts .. (z.aiming and "   (aiming)" or ""))
        gfx.text(6, 254, z.msg)
        gfx.text(6, h - 8, "Arrows move  T+arrow throw a bolt  Esc back away")
    elseif z.kind == "sequence" then
        gfx.text(6, 34, z.showing and "The signs burn in this order. Remember them."
            or "Press the keys for the signs, in order.")
        gfx.text(6, 47, "Round " .. z.round .. " of " .. #SEQ_LENGTHS)
        local n, box = #z.seq, 30
        local x0 = (w - n * (box + 6)) // 2
        for i = 1, n do
            local x = x0 + (i - 1) * (box + 6)
            gfx.rect(x, 80, box, box)
            local shown = z.showing and z.seq[i] or (i <= z.typed and z.seq[i])
            if shown then
                draw_sprite(x + 7, 87, 16, 16, SIGILS[shown])
            else
                gfx.text(x + 12, 100, "?")
            end
        end
        gfx.text(6, 150, "The signs and their keys:")
        for i = 1, 4 do
            local x = 60 + (i - 1) * 80
            gfx.rect(x, 162, 30, 30)
            draw_sprite(x + 7, 169, 16, 16, SIGILS[i])
            gfx.text(x + 12, 208, tostring(i))
        end
        gfx.text(6, h - 8, z.showing and "Any key: hide them   Esc back away" or "Keys 1-4   Esc back away")
    else
        gfx.text(6, 34, "Runes are cut into the stone. Pressing one turns")
        gfx.text(6, 47, "it and its neighbours. Match the carving above.")
        local size, gap = 40, 12
        local x0 = (w - RUNE_N * size - (RUNE_N - 1) * gap) // 2
        gfx.text(6, 72, "Carving:")
        for i = 1, RUNE_N do draw_rune(x0 + (i - 1) * (size + gap), 80, size, z.target[i]) end
        gfx.text(6, 150, "Stone:")
        for i = 1, RUNE_N do
            local x = x0 + (i - 1) * (size + gap)
            draw_rune(x, 158, size, z.cur[i])
            gfx.text(x + 17, 214, tostring(i))
        end
        gfx.text(6, 244, "Presses left: " .. z.moves)
        gfx.text(6, h - 8, "Keys 1-" .. RUNE_N .. "   Esc back away")
    end
    gfx.refresh()
end

function Game:draw_dead(w, h)
    gfx.clear(gfx.WHITE)
    gfx.color(gfx.BLACK)
    gfx.font(gfx.FONT_BOLD_14)
    gfx.text(6, 40, "You are dead.")
    gfx.font(gfx.FONT_MONO_12)
    gfx.text(6, 70, self.death_cause or "")
    local y = 100
    if self.death_note then   -- (a death with more to say: the Institute)
        for _, line in ipairs(wrap(self.death_note, 54)) do
            gfx.text(6, y - 8, line)
            y = y + 14
        end
        y = y + 6
    end
    for _, line in ipairs(self:run_summary()) do
        gfx.text(6, y, line)
        y = y + 16
    end
    gfx.text(6, h - 8, "Enter: new survivor  R: records  Q: quit")
    gfx.refresh()
end

-- ---------------------------------------------------------------------
-- Crafting screen (400x300): known recipes on the left, the selected one's
-- needs on the right (have/need for each input), then the log and keys.
-- ---------------------------------------------------------------------

local CRAFT_UI = {list_y = 38, row_h = 15, detail_x = 196}   -- one local: see the 200-local note in 35_crafting

function Game:draw_craft(w, h)
    local list = self:known_recipes()
    local c = self.craft_ui
    c.cursor = math.max(1, math.min(c.cursor, #list))
    gfx.clear(gfx.WHITE)
    gfx.color(gfx.BLACK)
    gfx.font(gfx.FONT_BOLD_14)
    gfx.text(6, 16, "Crafting")
    gfx.font(gfx.FONT_MONO_12)
    local camp = self.camps[hex_key(self.player.q, self.player.r)]
    local fire = self:fire_here()
        and ("Fire here: " .. (camp.until_hour - self.player.hours) .. "h left") or "No fire here"
    gfx.text(w - 6 - 7 * #fire, 16, fire)
    gfx.line(6, 22, w - 6, 22)

    -- the list: a mark for what you can make right now. It scrolls: only
    -- `rows` fit above the log, so the window follows the cursor.
    local rows = (h - 64 - CRAFT_UI.list_y) // CRAFT_UI.row_h
    local first = math.max(1, math.min(c.cursor - rows + 1, #list - rows + 1))
    for i, r in ipairs(list) do
      if i >= first and i < first + rows then
        local y = CRAFT_UI.list_y + (i - first) * CRAFT_UI.row_h
        local ready = self:craft_blocker(r) == nil
        if i == c.cursor then
            gfx.fill_rect(4, y - 11, CRAFT_UI.detail_x - 12, CRAFT_UI.row_h - 1)
            gfx.color(gfx.WHITE)
        end
        gfx.text(8, y, (ready and "+ " or "  ") .. r.name)
        gfx.color(gfx.BLACK)
      end
    end
    if first > 1 then gfx.text(CRAFT_UI.detail_x - 20, CRAFT_UI.list_y, "^") end
    if first + rows <= #list then
        gfx.text(CRAFT_UI.detail_x - 20, CRAFT_UI.list_y + (rows - 1) * CRAFT_UI.row_h, "v")
    end
    local unknown = 0
    for _, rr in ipairs(RECIPES) do if not self.known[rr.id] then unknown = unknown + 1 end end
    local ly = CRAFT_UI.list_y + math.min(#list, rows) * CRAFT_UI.row_h + 8
    if unknown > 0 and ly + 13 < h - 64 then
        gfx.text(8, ly, unknown .. " more unknown:")
        gfx.text(8, ly + 13, "read Scrawled Notes")
    end
    gfx.line(CRAFT_UI.detail_x - 4, 26, CRAFT_UI.detail_x - 4, h - 60)

    -- the selected recipe
    local r = list[c.cursor]
    if r then
        local x, y = CRAFT_UI.detail_x + 4, CRAFT_UI.list_y
        local icon = r.out and SPRITES[r.out[1]]
        if icon and draw_sprite then
            draw_sprite(w - 26, y - 12, SPRITE_W, SPRITE_H, icon)
        end
        gfx.text(x, y, r.out and ("Makes: " .. ITEM_DB[r.out[1]].name)
            or (r.base == "claim" and "Makes this ruin your camp")
            or (r.base and ("Builds at your camp"))
            or (r.mend and self:mend_text())
            or "Builds a campfire here")
        y = y + 18
        gfx.text(x, y, "Uses:")
        for _, iq in ipairs(Game.recipe_inputs(r)) do
            y = y + 13
            local have = self:count_item(iq[1])
            gfx.text(x + 7, y, ITEM_DB[iq[1]].name .. " " .. math.min(have, 99) .. "/" .. iq[2]
                .. (have >= iq[2] and "" or "  x"))
        end
        for _, tool in ipairs(r.tools or {}) do
            y = y + 13
            gfx.text(x, y, "Tool: " .. ITEM_DB[tool].name .. (self:count_item(tool) > 0 and "" or "  x"))
        end
        if r.fire then
            y = y + 13
            gfx.text(x, y, "Needs a fire" .. (self:fire_here() and "" or "  x"))
        end
        y = y + 18
        gfx.text(x, y, "Takes " .. self:craft_hours(r) .. "h")
        if r.repair then   -- repairs can fail (and burn a part)
            y = y + 14
            gfx.text(x, y, "Chance " .. self:repair_chance(r.repair) .. "% (Perception)")
        end
        y = y + 18
        local why = self:craft_blocker(r)
        for i, line in ipairs(wrap(why or "Ready: Enter to make it.", (w - x - 6) // 7)) do
            gfx.text(x, y + (i - 1) * 13, line)
        end
    end

    -- log and keys
    gfx.line(6, h - 52, w - 6, h - 52)
    local start_i = math.max(1, #self.log - 1)
    local yy = h - 36
    for i = start_i, #self.log do
        gfx.text(6, yy, self.log[i])
        yy = yy + 13
    end
    gfx.text(6, h - 6, "Up/Dn pick  Enter make  C/Esc back  Q quit")
    gfx.refresh()
end
-- ---------------------------------------------------------------------
-- Trade, Checkpoint and ending screens
-- ---------------------------------------------------------------------

local TRADE_UI = {rows = 12, row_h = 14, top = 50, col_x = {mine = 6, theirs = 204}, col_w = 190,
                  gate_intro = "Concrete blocks, razor wire, a tower whose searchlight never "
                      .. "switches off. A sergeant in a gas mask watches you come. 'Nobody "
                      .. "leaves the Churn without paper. Or without paying.'",
                  ending = {
                      permit = "The sergeant reads the permit twice, stamps it without looking "
                          .. "at you and lifts the barrier. On the far side the grass is only "
                          .. "grass. Behind you something vast and patient hums, and you know "
                          .. "you will dream of it every night.",
                      quiet = "The hum stops. For the first time since you came, the Churn is "
                          .. "silent: no wind in the wires, no birds, no count. You walk out the "
                          .. "way you came. The Checkpoint is empty, the barrier up, a radio on "
                          .. "the sergeant's desk hissing nothing at all.",
                      bribe = "The guards weigh the artifacts in their gloved hands. One of "
                          .. "them starts to cry and doesn't know why. They wave you through "
                          .. "without a word, and the barrier drops behind you like a closing eye.",
                  }}

function Game:draw_trade(w, h)
    local u, L = self.trade_ui, TRADE_UI
    gfx.clear(gfx.WHITE)
    gfx.color(gfx.BLACK)
    gfx.font(gfx.FONT_BOLD_14)
    local _, cfg = self:trade_partner()
    gfx.text(6, 16, cfg.name)
    gfx.font(gfx.FONT_MONO_12)
    gfx.text(200, 16, ("They ask x%.1f value"):format(cfg.markup))
    for _, col in ipairs({"mine", "theirs"}) do
        local x = L.col_x[col]
        local rows = self:trade_rows(col)
        local pick = col == "mine" and u.give or u.get
        gfx.color(gfx.BLACK)
        gfx.text(x, 36, col == "mine" and "Your bag  (you give)" or "Theirs  (you take)")
        local c = u.cursor[col]
        local first = math.max(1, c - L.rows + 1)
        for i = first, math.min(#rows, first + L.rows - 1) do
            local s = rows[i]
            local y = L.top + (i - first) * L.row_h
            local n = pick[s.item]
            local text = ("%-13s x%-2d %3d%s"):format(ITEM_DB[s.item].name:sub(1, 13), s.qty,
                                                    Game.item_value(s.item), n and (" +" .. n) or "")
            if i == c and col == u.col then
                gfx.color(gfx.BLACK)
                gfx.fill_rect(x - 2, y - 11, L.col_w, L.row_h)
                gfx.color(gfx.WHITE)
            elseif i == c then
                gfx.color(gfx.BLACK)
                gfx.rect(x - 2, y - 11, L.col_w, L.row_h)
            end
            gfx.text(x, y, text)
            gfx.color(gfx.BLACK)
        end
        if #rows == 0 then gfx.text(x, L.top, "(nothing)") end
    end
    gfx.color(gfx.BLACK)
    gfx.line(200, 26, 200, L.top + L.rows * L.row_h - 10)
    local give, ask = self:trade_totals()
    gfx.text(6, 234, ("You give %d   They ask %d"):format(give, ask))
    gfx.text(6, 252, u.msg or "")
    gfx.text(6, h - 8, "Arrows Enter:+1 E:-1 T:deal O:work Q:leave")
    gfx.refresh()
end

function Game:draw_gate(w, h)
    local u = self.gate_ui
    gfx.clear(gfx.WHITE)
    gfx.color(gfx.BLACK)
    gfx.font(gfx.FONT_BOLD_14)
    gfx.text(6, 22, "The Checkpoint")
    gfx.font(gfx.FONT_MONO_12)
    local y = 48
    for _, line in ipairs(wrap(TRADE_UI.gate_intro, 54)) do
        gfx.text(6, y, line)
        y = y + 14
    end
    y = y + 16
    for i, opt in ipairs(u.opts) do
        if i == u.cursor then
            gfx.fill_rect(4, y - 11, 240, 15)
            gfx.color(gfx.WHITE)
        end
        gfx.text(10, y, opt[1])
        gfx.color(gfx.BLACK)
        y = y + 20
    end
    if #u.opts == 1 then
        gfx.text(6, y + 10, ("You need a Churn Permit or %d artifacts."):format(GOAL.bribe))
    end
    gfx.text(6, h - 8, "Up/Dn pick  Enter choose  Q back")
    gfx.refresh()
end

function Game:draw_ending(w, h)
    local e = self.ending
    gfx.clear(gfx.WHITE)
    gfx.color(gfx.BLACK)
    gfx.font(gfx.FONT_BOLD_14)
    gfx.text(6, 30, "You left the Churn.")
    gfx.font(gfx.FONT_MONO_12)
    local y = 60
    local text = (TRADE_UI.ending[e.how] or "") .. (e.lore and (" " .. e.lore) or "")
    for _, line in ipairs(wrap(text, 54)) do
        gfx.text(6, y, line)
        y = y + 14
    end
    y = y + 8
    gfx.text(6, y, ("Artifacts carried out: %d"):format(e.artifacts))
    for _, line in ipairs(self:run_summary()) do
        y = y + 15
        gfx.text(6, y, line)
    end
    gfx.text(6, h - 8, "Enter: new survivor  R: records  Q: quit")
    gfx.refresh()
end
